#!/usr/bin/env python3
"""make_kernel.py — concatenate corpus + suite into one Kaggle script."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent
corpus = (ROOT / "corpus.py").read_text()
suite = (ROOT / "suite.py").read_text()

start = suite.index("try:  # when concatenated")
end = suite.index("except ImportError:\n    pass") + len("except ImportError:\n    pass")
suite = suite[:start] + "# corpus definitions are inlined above\n" + suite[end:]
suite = suite.replace("from __future__ import annotations\n", "")

preamble = '''#!/usr/bin/env python3
# Generated by experiments/make_kernel.py — do not edit on Kaggle.
from __future__ import annotations
import os
import subprocess
import sys
# DeepSeek-V2's remote modeling code still imports is_torch_fx_available,
# which modern transformers removed. Pin a compatible pair before any import.
subprocess.run(
    [sys.executable, "-m", "pip", "install", "-q",
     "transformers==4.46.3", "tokenizers==0.20.3",
     "bitsandbytes==0.48.2"],
    check=True,
)
try:
    import transformers.utils.import_utils as _iu
    if not hasattr(_iu, "is_torch_fx_available"):
        _iu.is_torch_fx_available = lambda: False
except Exception:
    pass
# Kaggle's preinstalled bitsandbytes works but ships without dist-info.
# transformers only needs a version string to gate its 4-bit path.
try:
    import importlib.metadata as _md
    _real_version = _md.version
    def _version(name):
        try:
            return _real_version(name)
        except Exception:
            return "0.45.5" if name == "bitsandbytes" else _real_version(name)
    _md.version = _version
except Exception:
    pass
try:
    import bitsandbytes as _bnb
    if not getattr(_bnb, "__version__", None):
        _bnb.__version__ = "0.45.5"
except Exception:
    pass
os.environ.setdefault("ATLAS_OUT", "/kaggle/working/data")
os.environ.setdefault("ATLAS_CACHE", "/kaggle/tmp/atlas_cache")
os.environ.setdefault("HF_HOME", "/kaggle/tmp/hf")
os.makedirs("/kaggle/working/data", exist_ok=True)
os.makedirs("/kaggle/tmp/atlas_cache", exist_ok=True)
'''

out = ROOT / "kaggle" / "suite.py"
out.parent.mkdir(exist_ok=True)
out.write_text(preamble + "\n" + corpus + "\n\n" + suite)

meta = {
    "id": "shariq101/deepseek-atlas-capture",
    "title": "DeepSeek Atlas Capture",
    "code_file": "suite.py",
    "language": "python",
    "kernel_type": "script",
    "is_private": True,
    "enable_gpu": True,
    "enable_internet": True,
    "machine_shape": "NvidiaTeslaT4",
    "dataset_sources": [],
    "competition_sources": [],
    "kernel_sources": [],
    "model_sources": [],
}
(ROOT / "kaggle" / "kernel-metadata.json").write_text(json.dumps(meta, indent=2))
print(f"wrote {out} ({len(out.read_text())/1024:.0f} KiB)")
